# shellcheck shell=bash disable=SC2034,SC2154,SC2088
# FEAT-045 T2: the per-CLI text the first-run wizard shows (lib/ai-cli.sh): the
# account each CLI needs, the login copy, the recovery hints and the first
# message sent to the agent. English is byte-identical to the text before the
# catalog; the Spanish twin is ../es/cli.sh. T3 added the choice hints, the
# night-shift reasons, the guard-state text and the OpenCode permission reasons.
BIB_MSG[cli.account.claude]='a Claude Pro or Max account (a paid plan)'
BIB_MSG[cli.account.antigravity]='a Google account'
BIB_MSG[cli.account.codex]='a ChatGPT account'
BIB_MSG[cli.account.opencode]='an OpenCode key, or another AI provider account'
BIB_MSG[cli.sub.claude]='Claude (Pro/Max)'
BIB_MSG[cli.sub.antigravity]='Google'
BIB_MSG[cli.sub.codex]='ChatGPT'
BIB_MSG[cli.sub.opencode]='Other / API'

BIB_MSG[cli.login.claude]='You will sign in with your Claude Pro or Max account.\n\n  1. Claude prints a long link. Open it in your browser\n     (touch and hold the link to copy it).\n  2. Sign in and tap Authorize.\n  3. The page shows a code. Copy it.\n  4. Come back here, paste the code at the prompt that\n     says "Paste code here" and press Enter ONCE.\n\nClaude also says "Opening browser". Ignore that line:\nthis box has no screen, so nothing opens.\n\nDo not press Enter again until you have the code.\n\n'
BIB_MSG[cli.login.claude_go]='Press Enter to get your sign-in link.'
BIB_MSG[cli.login.antigravity]='Antigravity (agy) signs in on its own screen. You will\nneed a Google account. When it opens:\n\n  1. Choose the login menu entry:  Google OAuth\n  2. agy prints a long sign-in link. Touch and hold it to\n     copy it (it may wrap over several lines: copy it\n     all), open it in your browser and sign in.\n  3. Paste the authorization code it gives you back into\n     agy.\n  4. agy may ask a few setup questions (colour,\n     telemetry, trust this folder). Accept the defaults.\n  5. Back at the agy prompt, type  /quit  (or Ctrl+D) to\n     hand control back to the setup.\n\nWhen you leave agy, the setup checks the login and goes on.\n'
BIB_MSG[cli.login.antigravity_go]='Press Enter to launch agy.'
BIB_MSG[cli.login.codex]='Codex signs in with your ChatGPT account, using a device\ncode. First, in your browser:\n\n  1. Open ChatGPT > Settings > Security and turn ON\n     "device code login" (also called "device\n     authorization"). Without it the login is refused.\n\nThen we start the login here:\n\n  2. This screen prints a link and a short code.\n  3. Open the link in a real browser (Chrome or Safari),\n     not in the ChatGPT app. Sign in, type the code and\n     approve. There is no QR code in this flow.\n  4. When you approve, this screen notices by itself: there\n     is nothing to paste back here.\n\n'
BIB_MSG[cli.login.codex_go]='Press Enter to start the Codex login.'
BIB_MSG[cli.login.opencode]='OpenCode signs in from its own menu. Before it opens:\n\n  1. In your browser, open  https://opencode.ai/auth ,\n     sign in, add your billing details and copy your API\n     key (OpenCode Go or Zen). Prefer another provider\n     you already pay for? Choose it in the menu instead.\n  2. We start OpenCode'\''s login now. Choose OpenCode Go or\n     OpenCode Zen and paste the key when it asks.\n  3. When it says the credential was saved, the setup\n     goes on by itself.\n\n'
BIB_MSG[cli.login.opencode_go]='Press Enter to start the OpenCode login.'

BIB_MSG[cli.fail.claude]='claude verification failed. Re-run install.sh to retry the login.'
BIB_MSG[cli.fail.antigravity]='agy login could not be verified. To retry: re-run '\''sudo /opt/buildersinabox/payload/install.sh'\'' and complete the Google OAuth (choose '\''Google OAuth'\'', paste the authorization code). If it keeps failing, confirm you finished the sign-in in the browser — a successful login writes a token to ~%s/.gemini/antigravity-cli/antigravity-oauth-token.'
BIB_MSG[cli.fail.codex]='codex login could not be verified. Most often the ChatGPT '\''device code login'\'' toggle is still off — enable it (ChatGPT → Settings → Security) and re-run '\''sudo /opt/buildersinabox/payload/install.sh'\''. Fallbacks: forward Codex'\''s local login port over SSH and log in normally ('\''ssh -L 1455:localhost:1455 %s@<box>'\'' then '\''codex login'\''), or set an API key with '\''codex login --api-key'\''. A successful login writes a token to ~%s/.codex/auth.json.'
BIB_MSG[cli.fail.opencode]='OpenCode is not logged in yet. To log in later: connect to the box%s, run '\''opencode auth login'\'', choose OpenCode Go or Zen and paste your key from https://opencode.ai/auth, then run '\''biab'\'' to continue the setup.'
BIB_MSG[cli.fail.opencode_as]=' as %s'

BIB_MSG[cli.first_prompt]='This is the first message on a brand-new Builders in a Box, and I may never have used anything like it. Run the tutorial skill and guide me through it, with these rules for your very first reply. One: welcome me in a few short lines. Say what this box is (a private computer that builds software with me and that I control from my phone), what the setup just installed (my AI, a private link to my devices, a workspace with ready-made skills) and what the next 10 minutes look like (connect GitHub, pick a first project, create it, a short tour). Two: always tell me what you are about to do, and why, before you do it, and wait for my go-ahead before anything that changes the box. Three: keep every message short and end it with one question. Four: read the install profile in /var/lib/buildersinabox/state.json so you call this machine by the right name.'

BIB_MSG[cli.hint.claude]='needs a paid Claude subscription (Pro or above). Guard and night shift.'
BIB_MSG[cli.hint.antigravity]='Google'\''s Antigravity (agy) — needs a Google account. Guard, no night shift.'
BIB_MSG[cli.hint.codex]='OpenAI Codex — sign in with your ChatGPT account. Guard (you approve it once), no night shift yet.'
BIB_MSG[cli.hint.opencode]='OpenCode — sign in with an OpenCode Go/Zen key or another provider. Partial guard. No night shift.'
BIB_MSG[cli.night.generic]='not available for %s yet'
BIB_MSG[cli.night.codex]='not wired for Codex yet (it has the pieces, not the unattended run)'
BIB_MSG[cli.night.antigravity]='not possible with Antigravity (agy) today: its command-line mode waits for a terminal an unattended run does not have, and it cannot log in without a person at a screen'
BIB_MSG[cli.night.opencode]='not available for OpenCode: no unattended mode with a spend cap and a tool guard that Builders in a Box can verify'
BIB_MSG[cli.gdisabled.codex]='(its hooks screen, or [features] hooks = false in config.toml)'
BIB_MSG[cli.note.codex_inline]='note: ~/.codex/config.toml has hooks of its own. Codex warns about two hook files each session; that is normal and not from BIAB.\n'
BIB_MSG[cli.note.opencode]='PARTIAL: %s deny rules in ~/.config/opencode/opencode.json: a different, smaller coverage than Claude Code'\''s or Codex'\''s.\nNot covered: a pipe into a shell or into fdisk (curl | bash), quoted targets (rm -rf "/"), rm -rf /*, commands inside bash -c,\na renamed fork bomb, a one-line heredoc, a command split over two lines, and any command that does not start with\nthe tool'\''s own name (sudo -E, env, VAR=1 rm, nohup, doubled spaces).\nKnown false positives: a quoted > /dev/sda inside text, git push -f to a branch whose name contains main or master.\nNot confirmed: subagents obeying these rules. Overridden by a project'\''s own opencode.json that allows everything, and by\nthe OPENCODE_CONFIG_CONTENT and OPENCODE_PERMISSION environment variables.\n'
BIB_MSG[cli.gtext.killswitch]='the guard rules ALREADY in ~/.config/opencode/opencode.json keep denying: the switch only stops BIAB from adding them. To remove them, delete from permission.bash the keys printed by: bash /opt/buildersinabox/payload/hooks/opencode-guard.sh keys'
BIB_MSG[cli.gtext.blocked]='base permissions not in place: BIAB adds its rules on top of the permission.bash it seeds in ~/.config/opencode/opencode.json, and that file is missing (sudo biab update creates it) or not in that shape (invalid JSON, JSONC, a blanket allow: fix the file, then run sudo biab update)'
BIB_MSG[cli.gtext.linked]='~/.config, ~/.config/opencode or opencode.json is a symbolic link and BIAB does not write through links: put the rules in its target yourself, or replace the link with a file'
BIB_MSG[cli.gtext.overridden]='the rules are in ~/.config/opencode/opencode.json, but OpenCode'\''s base permission check fails%s: an allow of yours that comes before ours is overridden where it overlaps, and an allow in an agent, a mode, ~/.opencode or the workspace opencode.json applies after ours'
BIB_MSG[cli.gtext.overridden_why]=' (%s)'
BIB_MSG[cli.gtext.missing]='the guard rules are not in ~/.config/opencode/opencode.json yet: run sudo biab update'
BIB_MSG[cli.gtext.partial]='some guard rules in ~/.config/opencode/opencode.json are missing, were changed, or are overridden by a rule of yours that comes after them'
BIB_MSG[cli.perm.nohome]='the box user'\''s home folder could not be found'
BIB_MSG[cli.perm.owner]='refused: the home folder %s has no ordinary owner to write as'
BIB_MSG[cli.perm.link_home]='a symbolic link in the way (BIAB never reads or writes through links in your home folder): %s'
BIB_MSG[cli.perm.jsonc_next]='%s/opencode.jsonc exists next to opencode.json, and BIAB does not merge JSONC'
BIB_MSG[cli.perm.no_config]='%s does not exist, and OpenCode'\''s default is to allow edits and shell commands'
BIB_MSG[cli.perm.link]='a symbolic link in the way: %s'
BIB_MSG[cli.perm.jsonc]='%sc exists, and BIAB does not read JSONC'
BIB_MSG[cli.perm.bad_json]='%s is not valid JSON'
BIB_MSG[cli.perm.agent_file]='an agent file under %s allows actions without asking'
BIB_MSG[cli.perm.with_why]='%s: %s'
BIB_MSG[cli.perm.why_not_object]='its top level is not a JSON object'
BIB_MSG[cli.perm.why_allows]='it allows actions without asking, after the global rules'
BIB_MSG[cli.perm.why_no_rules]='it has no permission rules'
BIB_MSG[cli.perm.why_wildcard]='a wildcard permission rule can override the rules that ask'
BIB_MSG[cli.perm.why_agent_mode]='an agent or mode rule in the same file allows actions without asking (OpenCode applies it after the global rules)'
BIB_MSG[cli.perm.why_edit]='permission.edit does not ask or deny'
BIB_MSG[cli.perm.why_bash]='permission.bash does not ask or deny by default'
BIB_MSG[cli.perm.unchecked]='OpenCode'\''s settings could not be checked'
